public class JavadocSkeletonBuilderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String clamp = "/**\n"
                + " * TODO describe clamp.\n"
                + " *\n"
                + " * @param value TODO\n"
                + " * @param low TODO\n"
                + " * @param high TODO\n"
                + " * @return TODO\n"
                + " */";
        check("method with params and return", clamp,
                JavadocSkeletonBuilder.skeletonFor("public static int clamp(int value, int low, int high)", ""));

        String moved = "/**\n"
                + " * TODO describe move.\n"
                + " *\n"
                + " * @param dx TODO\n"
                + " * @param dy TODO\n"
                + " */";
        check("void method has no return tag", moved,
                JavadocSkeletonBuilder.skeletonFor("public void move(int dx, int dy)", ""));

        String size = "/**\n"
                + " * TODO describe size.\n"
                + " *\n"
                + " * @return TODO\n"
                + " */";
        check("no parameters", size, JavadocSkeletonBuilder.skeletonFor("public int size()", ""));

        String reset = "/**\n"
                + " * TODO describe reset.\n"
                + " */";
        check("void method with no parameters", reset,
                JavadocSkeletonBuilder.skeletonFor("public void reset()", ""));

        String indented = "    /**\n"
                + "     * TODO describe twice.\n"
                + "     *\n"
                + "     * @param n TODO\n"
                + "     * @return TODO\n"
                + "     */";
        check("indented skeleton", indented,
                JavadocSkeletonBuilder.skeletonFor("static int twice(int n)", "    "));

        String varargs = "/**\n"
                + " * TODO describe join.\n"
                + " *\n"
                + " * @param parts TODO\n"
                + " * @return TODO\n"
                + " */";
        check("varargs parameter", varargs,
                JavadocSkeletonBuilder.skeletonFor("public static String join(String... parts)", ""));

        check("null signature", "", JavadocSkeletonBuilder.skeletonFor(null, ""));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

