public class JavadocSkeletonBuilder {

    public static String skeletonFor(String signature, String indent) {
        if (signature == null) {
            return "";
        }
        int open = signature.indexOf('(');
        int close = signature.lastIndexOf(')');
        if (open < 0 || close < open) {
            return "";
        }

        String[] head = signature.substring(0, open).trim().split("\\s+");
        String methodName = head[head.length - 1];
        String returnType = head.length >= 2 ? head[head.length - 2] : "void";

        java.util.List<String> tags = new java.util.ArrayList<>();
        String inside = signature.substring(open + 1, close).trim();
        if (!inside.isEmpty()) {
            for (String parameter : inside.split(",")) {
                String[] words = parameter.trim().split("\\s+");
                tags.add(" * @param " + words[words.length - 1] + " TODO");
            }
        }
        if (!returnType.equals("void")) {
            tags.add(" * @return TODO");
        }

        java.util.List<String> lines = new java.util.ArrayList<>();
        lines.add("/**");
        lines.add(" * TODO describe " + methodName + ".");
        if (!tags.isEmpty()) {
            lines.add(" *");
            lines.addAll(tags);
        }
        lines.add(" */");

        StringBuilder skeleton = new StringBuilder();
        for (int i = 0; i < lines.size(); i++) {
            if (i > 0) {
                skeleton.append("\n");
            }
            skeleton.append(indent).append(lines.get(i));
        }
        return skeleton.toString();
    }
}
